'use strict';
LocationEngine.upgrade(state);
NAV.splice(3,0,['freezers','▦','Freezers']);
let homeFilter='All';
const lp=()=>LocationEngine.calculate(state,CookieEngine);
const homeTabs=()=>`<div class="filters home-tabs" aria-label="Location">${['All','WV','OH'].map(h=>`<button class="filter ${homeFilter===h?'active':''}" data-home="${h}">${h==='All'?'Both homes':h}</button>`).join('')}</div>`;
const currentHomes=()=>homeFilter==='All'?LocationEngine.homes:[homeFilter];
notice=()=>'';
head=(eyebrow,title,sub,buttons='')=>`<div class="page-head"><div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="page-buttons">${buttons}</div></div>`;
overview=function(){const p=lp();return head('','Overview',`${state.season} season · WV & OH`,`<button class="btn" data-action="new">＋ Add request</button>`)+metrics([['Cookies requested',fmt(p.requested),`${p.active.length} requests`],['Batches remaining',fmt(p.remaining),`${p.batches} planned · whole batches`],['Shopping subtotal',p.locationIngredients.some(i=>i.spend==null)?'Incomplete':money(p.shoppingSpend),p.locationIngredients.some(i=>i.spend==null)?money(p.shoppingSpend)+' in known prices':'Packages still needed'],['Donation surplus',fmt(p.extra),'Planned cookies beyond requests']])+`<div class="grid-two">${LocationEngine.homes.map(h=>{const rows=p.locationRows.filter(r=>r.home===h&&r.assigned>0),stock=Object.values(p.freezer[h]).reduce((a,b)=>a+b,0);return `<section class="panel"><div class="panel-head"><h2>${h}</h2><button class="text-link" data-open-home="${h}" data-go="bake">Bake plan →</button></div><div class="panel-body"><div class="home-summary"><div><strong>${rows.reduce((n,r)=>n+r.remaining,0)}</strong><small>Batches left</small></div><div><strong>${fmt(stock)}</strong><small>Cookies in freezer</small></div><div><strong>${state.requests.filter(o=>o.home===h&&!['Cancelled','Handed over'].includes(o.status)).length}</strong><small>Open requests</small></div></div>${rows.slice(0,5).map(r=>`<div class="person-row"><div class="person-info"><strong>${esc(r.name)}</strong><small>${r.done} baked · ${r.assigned} planned</small></div><b>${r.remaining} left</b></div>`).join('')||'<div class="blank">No batches planned.</div>'}</div></section>`;}).join('')}</div><section class="panel"><div class="panel-head"><h2>Upcoming handoffs</h2><button class="text-link" data-go="requests">All requests →</button></div><div class="panel-body">${p.active.filter(o=>o.status!=='Handed over').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6).map(o=>`<div class="person-row"><span class="home-badge">${esc(o.home)}</span><div class="person-info"><strong>${esc(o.name)}</strong><small>${date(o.date)} · ${fmt(Object.values(o.items).reduce((a,b)=>a+b,0))} cookies</small></div><button class="text-link" data-person="${esc(o.id)}">Details →</button></div>`).join('')||'<div class="blank">No requests yet.</div>'}</div></section>`;};
bake=function(){const p=lp();return head('','Bake plan','Assign whole batches to a kitchen. Record them after baking.',`<button class="btn quiet" data-action="print">Print</button><button class="btn" data-action="record-bake">Record baking</button>`)+homeTabs()+`<section class="panel table-wrap"><table><thead><tr><th>Recipe</th><th>Kitchen</th><th class="num">Batches</th><th class="num">Baked</th><th class="num">Remaining</th><th></th></tr></thead><tbody>${p.locationRows.filter(r=>currentHomes().includes(r.home)&&(r.assigned>0||r.done>0)).map(r=>`<tr><td><button class="text-link" data-recipe="${r.id}">${esc(r.name)}</button><small>${r.yield} cookies / batch · ${r.batches} batches total</small></td><td><span class="home-badge">${r.home}</span></td><td class="num">${r.assigned}</td><td class="num">${r.done}</td><td class="num"><strong>${r.remaining}</strong></td><td><button class="text-link" data-assign="${r.id}">Assign kitchens</button></td></tr>`).join('')}</tbody></table>${!p.locationRows.length?'<div class="blank">Add a request to create a bake plan.</div>':''}</section><p class="list-note">${fmt(p.produced)} planned cookies · ${fmt(p.extra)} available for donations. Baking deducts pantry ingredients and adds cookies to a freezer.</p>`;};
shopping=function(){const p=lp();const spend=p.locationIngredients.reduce((n,i)=>n+currentHomes().reduce((a,h)=>a+(i.byHome[h].spend||0),0),0),packages=p.locationIngredients.reduce((n,i)=>n+currentHomes().reduce((a,h)=>a+(i.byHome[h].buy||0),0),0),incomplete=p.locationIngredients.some(i=>currentHomes().some(h=>i.byHome[h].spend==null));return head('','Shopping list','For batches still to bake. Shortages are calculated separately for each home.',`<button class="btn quiet" data-action="csv-locations">Export</button><button class="btn quiet" data-action="print">Print</button><button class="btn" data-go="ingredients">Pantry</button>`)+homeTabs()+`<section class="panel table-wrap"><table><thead><tr><th>Ingredient / package</th>${currentHomes().map(h=>`<th class="num">${h} need / have / buy</th>`).join('')}<th class="num">Cost</th><th></th></tr></thead><tbody>${p.locationIngredients.map(i=>{const count=currentHomes().reduce((n,h)=>n+(i.byHome[h].buy||0),0),missing=currentHomes().some(h=>i.byHome[h].buy==null);return `<tr><td><button class="text-link" data-ingredient="${i.id}"><strong>${esc(i.name)}</strong></button><small>${esc(i.package)} · ${fmt(i.unitsPerPackage)} ${esc(i.unit)} usable</small></td>${currentHomes().map(h=>{const v=i.byHome[h];return `<td class="num"><strong>${v.buy==null?'Needs conversion':v.buy+' to buy'}</strong><small>${fmt(v.amount)} ${esc(i.unit)} needed</small><small>${fmt(v.have)} packages in pantry</small></td>`;}).join('')}<td class="num">${missing?'Incomplete':count===0?money(0):i.price==null?'Price needed':money(count*i.price)}</td><td>${count>0&&!missing?`<button class="text-link" data-purchase="${i.id}">Add purchase</button>`:''}</td></tr>`;}).join('')}</tbody></table>${!p.locationIngredients.length?'<div class="blank">Nothing to shop for.</div>':''}<div class="table-total"><span>${packages} packages to buy</span><strong>${incomplete?'Known subtotal':'Estimated total'}: ${money(spend)}</strong></div></section><p class="list-note">Both homes adds their rounded package shortages. Transfer stock between homes to reduce purchases. Missing prices are excluded from the subtotal.</p>`;};
function freezers(){const p=lp();return head('','Freezers','Finished cookies available at each home.',`<button class="btn quiet" data-action="freezer-count">Set stock</button><button class="btn quiet" data-action="transfer">Transfer stock</button><button class="btn" data-action="donation">Record donation</button>`)+homeTabs()+`<div class="grid-two">${currentHomes().map(h=>`<section class="panel"><div class="panel-head"><h2>${h} freezer</h2></div><div class="panel-body">${Object.entries(p.freezer[h]).filter(([,q])=>q>0).map(([id,q])=>`<div class="person-row"><div class="person-info"><strong>${esc(state.recipes.find(r=>r.id==id)?.name||'Archived recipe')}</strong></div><b>${fmt(q)} cookies</b></div>`).join('')||'<div class="blank">No cookies recorded.</div>'}</div></section>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Recent activity</h2></div><div class="panel-body">${state.movements.slice(-12).reverse().map(m=>`<div class="person-row"><div class="person-info"><strong>${esc(m.kind.replaceAll('-',' '))} · ${esc(state.recipes.find(r=>r.id===m.recipeId)?.name||state.ingredients.find(i=>i.id===m.ingredientId)?.name||'')}</strong><small>${new Date(m.at).toLocaleDateString()} · ${esc(m.home||m.from)}${m.to?' → '+esc(m.to):m.storeHome&&m.storeHome!==m.home?' → '+esc(m.storeHome):''}${m.destination?' · '+esc(m.destination):''}</small></div><b>${fmt(m.cookies||m.quantity||0)}</b></div>`).join('')||'<div class="blank">No activity yet.</div>'}</div></section>`;}
const oldIngredients=ingredients;
ingredients=function(){return oldIngredients().replace('</section><p class="list-note">','</section><button class="btn quiet" data-action="transfer">Transfer stock</button><p class="list-note">');};
settings=function(){return head('','Settings','Season and kitchen records.')+`<div class="grid-two"><section class="panel"><div class="panel-head"><h2>Season</h2></div><div class="panel-body"><p>${state.season}</p><button class="btn quiet" data-action="new-season">Start next season</button><p class="list-note">Archives requests and activity. Recipes, prices, pantry and freezer stock carry forward.</p>${state.seasons.map((s,n)=>`<button class="text-link" data-season-export="${n}">Download ${s.season} archive</button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Backup</h2></div><div class="panel-body"><button class="btn" data-action="backup">Download backup</button><button class="btn quiet" data-action="restore">Restore backup</button><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="list-note">Includes recipes, requests, pantry stock and baking records.</p></div></section></div>`;};
function smallForm(title,fields,submit){modal(modalHead(title,'')+`<form class="modal-body" id="location-form">${fields}<div id="form-error" class="alert-number" role="alert"></div><div class="modal-actions"><button class="btn quiet" type="button" data-action="close">Cancel</button><button class="btn">Save</button></div></form>`);$('#location-form').onsubmit=e=>{e.preventDefault();try{submit(new FormData(e.target));persist();$('#modal').close();render();}catch(err){$('#form-error').textContent=err.message;}};}
const homeSelect=(name,label,value='WV')=>`<label class="field">${label}<select name="${name}">${LocationEngine.homes.map(h=>`<option ${value===h?'selected':''}>${h}</option>`).join('')}</select></label>`;
function recordBaking(){smallForm('Record baking',`<label class="field">Recipe<select name="recipe">${sortedRecipes().filter(r=>!r.archived).map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><div class="form-grid">${homeSelect('home','Kitchen')}${homeSelect('store','Freezer')}</div><label class="field">Full batches<input name="batches" type="number" min="1" step="1" value="1" required></label><p class="list-note">Uses pantry stock at the kitchen and adds finished cookies to the freezer.</p>`,f=>LocationEngine.bake(state,CookieEngine,Number(f.get('recipe')),f.get('home'),f.get('store'),Number(f.get('batches'))));}
function stockTransfer(){smallForm('Transfer stock',`<label class="field">Item<select name="item">${sortedIngredients().filter(i=>!i.archived).map(i=>`<option value="i:${i.id}">${esc(i.name)} · packages</option>`).join('')}${sortedRecipes().map(r=>`<option value="r:${r.id}">${esc(r.name)} · cookies</option>`).join('')}</select></label><div class="form-grid">${homeSelect('from','From')}${homeSelect('to','To','OH')}</div><label class="field">Quantity<input name="quantity" type="number" min="0.000001" step="any" required></label>`,f=>{const [type,id]=f.get('item').split(':');LocationEngine.transfer(state,type==='i'?'ingredient-transfer':'cookie-transfer',Number(id),f.get('from'),f.get('to'),Number(f.get('quantity')),CookieEngine);});}
const oldDrawIngredient=drawIngredientEditor;
drawIngredientEditor=function(){oldDrawIngredient();const input=document.querySelector('[data-ingredient-field="pantry"]');if(input){input.closest('label').innerHTML=`Pantry stock<p class="list-note">Edit WV and OH stock on the Pantry page.</p>`;}};
const oldPersist=persist;
persist=function(){LocationEngine.upgrade(state);oldPersist();};
const oldRender=render;
render=function(){LocationEngine.upgrade(state);if(view==='guest')view='overview';if(view==='freezers'){view='overview';oldRender();view='freezers';$('#main').innerHTML=freezers();$('#nav').innerHTML=NAV.map(([v,i,n])=>`<button data-go="${v}" class="${view===v?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#mobile-current-page').textContent='Freezers';}else oldRender();$('#season-heading').textContent=state.season+' season';$('#season-label').textContent='WV · OH';};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.home){homeFilter=d.home;render();}if(d.openHome){homeFilter=d.openHome;render();}
 if(d.action==='record-bake')recordBaking();if(d.action==='transfer')stockTransfer();
 if(d.assign!=null){const id=Number(d.assign),r=lp().recipePlans.find(r=>r.id===id),oh=lp().locationRows.find(r=>r.id===id&&r.home==='OH').assigned;smallForm('Assign '+r.name,`<p>${r.batches} full batches total. Recorded batches stay assigned to their kitchen.</p><label class="field">OH batches<input name="oh" type="number" min="0" max="${r.batches}" step="1" value="${oh}" required></label><p class="list-note">Remaining batches are assigned to WV.</p>`,f=>{const n=Number(f.get('oh'));if(!Number.isInteger(n)||n<0||n>r.batches)throw Error('Enter a valid whole batch count.');const doneOH=lp().locationRows.find(x=>x.id===id&&x.home==='OH').done,doneWV=lp().locationRows.find(x=>x.id===id&&x.home==='WV').done;if(n<doneOH||r.batches-n<doneWV)throw Error('Recorded batches cannot move between kitchens. Transfer finished cookies instead.');state.batchAssignments[id]={OH:n};});}
 if(d.purchase!=null){const i=state.ingredients.find(i=>i.id===Number(d.purchase));smallForm('Add '+i.name+' purchase',homeSelect('home','Pantry')+`<label class="field">Packages bought<input name="packages" type="number" min="0.000001" step="any" required></label>`,f=>{const n=Number(f.get('packages'));if(!(n>0))throw Error('Enter a positive quantity.');i.stock[f.get('home')]+=n;state.movements.push({id:crypto.randomUUID(),kind:'purchase',ingredientId:i.id,home:f.get('home'),quantity:n,at:new Date().toISOString()});});}
 if(d.action==='donation'){smallForm('Record donation',`<label class="field">Recipe<select name="recipe">${sortedRecipes().map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label>${homeSelect('home','Freezer')}<label class="field">Cookies<input name="quantity" type="number" min="1" step="1" required></label><label class="field">Recipient<input name="destination" required maxlength="100" placeholder="School, station or service group"></label>`,f=>{const id=Number(f.get('recipe')),h=f.get('home'),n=Number(f.get('quantity'));if(!Number.isInteger(n)||n<1||n>(lp().freezer[h][id]||0))throw Error('Not enough cookies in this freezer.');state.movements.push({id:crypto.randomUUID(),kind:'donation',recipeId:id,home:h,quantity:n,destination:f.get('destination'),at:new Date().toISOString()});});}
 if(d.action==='new-season'){smallForm('Start next season',`<label class="field">Year<input name="year" type="number" min="${state.season+1}" max="2100" step="1" value="${state.season+1}" required></label><p class="list-note">Download a backup first. Current requests and activity are archived.</p>`,f=>{const year=Number(f.get('year'));if(!Number.isInteger(year)||year<=state.season||year>2100)throw Error('Choose a later year.');const frozen=lp().freezer;state.seasons.push({season:state.season,requests:structuredClone(state.requests),movements:structuredClone(state.movements),recipes:structuredClone(state.recipes),ingredients:structuredClone(state.ingredients)});state.requests=[];state.batchAssignments={};state.movements=[];for(const h of LocationEngine.homes)for(const [id,q] of Object.entries(frozen[h]))if(q>0)state.movements.push({id:crypto.randomUUID(),kind:'bake',recipeId:Number(id),home:h,storeHome:h,batches:0,cookies:q,carryover:true,at:new Date().toISOString()});state.recipes.forEach(r=>r.baked=0);state.season=year;});}
 if(d.seasonExport!=null)downloadJSON(state.seasons[Number(d.seasonExport)],'Cookie-Season-'+state.seasons[Number(d.seasonExport)].season+'-Archive.json');
 if(d.action==='csv-locations'){const rows=[['Ingredient','Package','WV packages to buy','OH packages to buy','Price per package'],...lp().locationIngredients.map(i=>[i.name,i.package,i.byHome.WV.buy??'Conversion needed',i.byHome.OH.buy??'Conversion needed',i.price??'Missing'])];const csv=rows.map(row=>row.map(v=>'"'+(/^[=+@\-]/.test(String(v))?"'":'')+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='Cookie-Season-Shopping.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.stockId!=null){const n=Number(e.target.value);if(!Number.isFinite(n)||n<0){toast('Enter zero or a positive pantry amount.');render();return;}state.ingredients.find(i=>i.id===Number(d.stockId)).stock[d.stockHome]=n;persist();render();}});
render();
// A completed handoff consumes finished inventory exactly once.
openPerson=function(id){const o=state.requests.find(o=>o.id===id);if(!o)return;const p=lp(),count=Object.values(o.items).reduce((a,b)=>a+b,0);modal(modalHead(o.name,`${date(o.date)} · ${o.home} · ${esc(o.method)} · ${status(o.status)}`)+`<div class="modal-body"><div class="packing-total">${fmt(count)} cookies</div>${o.note?`<div class="notice">${esc(o.note)}</div>`:''}<ul class="checklist">${Object.entries(o.items).map(([rid,q])=>`<li><input class="check" type="checkbox" data-pack="${esc(o.id)}" data-rid="${rid}" ${o.packed?.[rid]?'checked':''} aria-label="Packed ${esc(state.recipes.find(r=>r.id==rid)?.name)}"><span>${esc(state.recipes.find(r=>r.id==rid)?.name)}</span><b>${fmt(q)}</b></li>`).join('')}</ul><p class="list-note">Estimated ingredient share: ${money(personCost(o))}. Missing prices are excluded.</p><div class="modal-actions"><button class="btn quiet" data-action="print">Print</button>${o.status==='Handed over'?'<button class="btn" data-action="close">Done</button>':`<button class="btn quiet" data-edit="${esc(o.id)}">Edit request</button><button class="btn" data-handoff="${esc(o.id)}">Record handoff</button>`}</div></div>`);};
document.addEventListener('click',e=>{const b=e.target.closest('button[data-handoff]');if(!b)return;const o=state.requests.find(o=>o.id===b.dataset.handoff);if(!o||o.status==='Handed over')return;smallForm('Handoff to '+o.name,homeSelect('home','Take cookies from',o.home)+`<p class="list-note">Removes this request’s cookies from the selected freezer.</p>`,f=>{const h=f.get('home'),stock=lp().freezer[h];for(const [rid,q] of Object.entries(o.items))if(q>(stock[rid]||0))throw Error('Not enough '+state.recipes.find(r=>r.id==rid)?.name+' in '+h+'.');for(const [rid,q] of Object.entries(o.items))state.movements.push({id:crypto.randomUUID(),kind:'handoff',recipeId:Number(rid),home:h,quantity:q,requestId:o.id,at:new Date().toISOString()});o.status='Handed over';});});

const validateBaseBackup=validateBackup;
validateBackup=function(data){validateBaseBackup(data);if(data.locations&&!Array.isArray(data.locations))throw Error('Invalid locations.');for(const i of data.ingredients)if(i.stock&&LocationEngine.homes.some(h=>!Number.isFinite(i.stock[h])||i.stock[h]<0))throw Error('Invalid pantry stock.');for(const o of data.requests)if(o.home&&!LocationEngine.homes.includes(o.home))throw Error('Invalid request home.');if(data.movements&&!Array.isArray(data.movements))throw Error('Invalid stock records.');for(const m of data.movements||[]){if(!['bake','cookie-transfer','ingredient-transfer','purchase','handoff','donation','freezer-count'].includes(m.kind))throw Error('Invalid stock activity.');if(m.kind==='freezer-count'&&!Number.isFinite(m.adjustment))throw Error('Invalid freezer count.');if(m.home&&!LocationEngine.homes.includes(m.home)||m.from&&!LocationEngine.homes.includes(m.from)||m.to&&!LocationEngine.homes.includes(m.to))throw Error('Invalid stock location.');for(const key of ['quantity','cookies','batches'])if(m[key]!=null&&(!Number.isFinite(m[key])||m[key]<0))throw Error('Invalid stock quantity.');}return data;};

document.addEventListener('click',e=>{if(!e.target.closest('button[data-action="freezer-count"]'))return;smallForm('Set freezer stock',`<label class="field">Recipe<select name="recipe">${sortedRecipes().map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label>${homeSelect('home','Freezer')}<label class="field">Actual cookies in freezer<input name="quantity" type="number" min="0" step="1" required></label><p class="list-note">Use for starting stock or correcting a count. This does not consume pantry ingredients.</p>`,f=>{const id=Number(f.get('recipe')),home=f.get('home'),n=Number(f.get('quantity'));if(!Number.isInteger(n)||n<0)throw Error('Enter a whole cookie count of zero or more.');state.movements.push({id:crypto.randomUUID(),kind:'freezer-count',recipeId:id,home,quantity:n,adjustment:n-(lp().freezer[home][id]||0),at:new Date().toISOString()});});});
